// app/docs/[slug]/page.tsx - segment-level page cache (ISR)
export const revalidate = 300;               // seconds; false = until purged

export default async function DocPage({ params }: { params: { slug: string } }) {
  const page = await renderDoc(params.slug); // runs on a miss only
  return <article dangerouslySetInnerHTML={{ __html: page.html }} />;
}

